 "content": "def transform(grid):
    # A full-width 5 divides the two patterns. Compare how much each color's
    # cell count grows from the upper region to the lower region.
    divider = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    upper, lower = grid[:divider], grid[divider + 1:]
    colors = {v for row in grid for v in row if v not in (0, 5)}
    growth = {c: sum(row.count(c) for row in lower) - sum(row.count(c) for row in upper) for c in colors}
    winner = max(colors, key=lambda c: growth[c])
    return [[winner, winner], [winner, winner]]
